WITH
drug1_source AS (
  SELECT concept_id FROM omop.concept WHERE vocabulary_id = 'RxNorm' AND concept_code = '9863' AND invalid_reason IS NULL
),
drug1_mapped AS (
  SELECT concept_id_2 AS concept_id FROM drug1_source ds JOIN omop.concept_relationship cr ON ds.concept_id = cr.concept_id_1 WHERE cr.relationship_id = 'Maps to'
),
drug1_concepts AS (
  SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM drug1_mapped dm JOIN omop.concept c ON dm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
),
drug2_source AS (
  SELECT concept_id FROM omop.concept WHERE vocabulary_id = 'RxNorm' AND concept_code = '161' AND invalid_reason IS NULL
),
drug2_mapped AS (
  SELECT concept_id_2 AS concept_id FROM drug2_source ds JOIN omop.concept_relationship cr ON ds.concept_id = cr.concept_id_1 WHERE cr.relationship_id = 'Maps to'
),
drug2_concepts AS (
  SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM drug2_mapped dm JOIN omop.concept c ON dm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
),
drug3_source AS (
  SELECT concept_id FROM omop.concept WHERE vocabulary_id = 'RxNorm' AND concept_code = '8591' AND invalid_reason IS NULL
),
drug3_mapped AS (
  SELECT concept_id_2 AS concept_id FROM drug3_source ds JOIN omop.concept_relationship cr ON ds.concept_id = cr.concept_id_1 WHERE cr.relationship_id = 'Maps to'
),
drug3_concepts AS (
  SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM drug3_mapped dm JOIN omop.concept c ON dm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
)
SELECT COUNT(DISTINCT person_id) FROM (
  SELECT person_id FROM omop.drug_exposure WHERE drug_concept_id IN (SELECT concept_id FROM drug1_concepts)
  UNION
  SELECT person_id FROM omop.drug_exposure WHERE drug_concept_id IN (SELECT concept_id FROM drug2_concepts)
  UNION
  SELECT person_id FROM omop.drug_exposure WHERE drug_concept_id IN (SELECT concept_id FROM drug3_concepts)
) AS union_patients;

WITH condition1_source AS (
  SELECT concept_id FROM omop.concept WHERE vocabulary_id = 'SNOMED' AND concept_code = '14669001' AND invalid_reason IS NULL
),
condition1_mapped AS (
  SELECT concept_id_2 AS concept_id FROM condition1_source cs JOIN omop.concept_relationship cr ON cs.concept_id = cr.concept_id_1 WHERE cr.relationship_id = 'Maps to' AND cr.invalid_reason IS NULL
),
condition1_concepts AS (
  SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM condition1_mapped cm JOIN omop.concept c ON cm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
),
condition1_occurrences AS (
  SELECT co.person_id, co.condition_start_date AS start_date FROM omop.condition_occurrence co JOIN condition1_concepts c1 ON co.condition_concept_id = c1.concept_id
),
condition2_source AS (
  SELECT concept_id FROM omop.concept WHERE vocabulary_id = 'SNOMED' AND concept_code = '271737000' AND invalid_reason IS NULL
),
condition2_mapped AS (
  SELECT concept_id_2 AS concept_id FROM condition2_source cs JOIN omop.concept_relationship cr ON cs.concept_id = cr.concept_id_1 WHERE cr.relationship_id = 'Maps to' AND cr.invalid_reason IS NULL
),
condition2_concepts AS (
  SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM condition2_mapped cm JOIN omop.concept c ON cm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
),
condition2_occurrences AS (
  SELECT co.person_id, co.condition_start_date AS start_date FROM omop.condition_occurrence co JOIN condition2_concepts c2 ON co.condition_concept_id = c2.concept_id
)
SELECT COUNT(DISTINCT a.person_id) AS patient_count
FROM condition1_occurrences a
JOIN condition2_occurrences b ON a.person_id = b.person_id
WHERE CAST(
  EXTRACT(epoch FROM CAST(GREATEST(a.start_date, b.start_date) AS TIMESTAMP) - CAST(LEAST(a.start_date, b.start_date) AS TIMESTAMP)) / 86400 AS BIGINT
) <= 30;

